style.css:
@-moz-document domain("discord.com") {
/* Fundo com GIF animado */
  body {
    background: url("https://i.pinimg.com/originals/ed/e8/39/ede839e3e6bbbc55ee899b9cca310a9b.gif")
                no-repeat center center fixed !important;
    background-size: cover !important;
    color: #4a4a4a !important;
    font-family: "Comic Neue", "Segoe UI", Arial, sans-serif !important;
  }

  /* Overlay suave para legibilidade (camada translúcida) */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background-color: rgba(255, 245, 248, 0.70); /* rosa pastel translúcido */
    pointer-events: none;
    z-index: 0;
  }

  /* Garantir que o conteúdo fique acima do overlay */
  #app-mount, .appMount-3lHmkl, .app-2CXKsg {
    position: relative !important;
    z-index: 1 !important;
    backdrop-filter: none !important;
  }

  /* Sidebar (mais estável usando data-theme e containers comuns) */
  .sidebar-2K8pFh,
  nav[aria-label="Servers"],
  .container-1eFtFS {
    background-color: rgba(255, 230, 235, 0.85) !important;
    border-right: 2px solid #ffb6c9 !important;
  }

  /* Servidores (bolinhas) */
  .listItem-3SmSlK,
  .wrapper-1Rf91z {
    background-color: #ffd6e0 !important;
    border-radius: 50% !important;
    border: 2px solid #ffb6c9 !important;
    transition: transform 0.3s ease;
  }
  .listItem-3SmSlK:hover,
  .wrapper-1Rf91z:hover {
    transform: scale(1.1);
    background-color: #ffb6c9 !important;
  }

  /* Canal selecionado */
  .selected-2TbFuo,
  .selected-3H3K0R,
  .modeSelected-3D0zZy {
    background-color: #ffcce0 !important;
    color: #a64d79 !important;
    border-radius: 10px !important;
    font-weight: bold !important;
    box-shadow: 0 0 8px #ffb6c9;
  }

  /* Barra superior / header do chat */
  .title-31SJ6t,
  .container-1r6BKw,
  .toolbar-3_r2xA {
    background-color: rgba(255, 230, 235, 0.85) !important;
    color: #a64d79 !important;
  }

  /* Mensagens (caixas suaves) */
  .message-2qnXI6,
  .messageListItem-ZZ7v6g,
  .contents-2MsGLg {
    background-color: rgba(255, 240, 245, 0.85) !important;
    border-radius: 12px !important;
    padding: 8px !important;
    margin-bottom: 8px !important;
    border: 1px solid #ffd6e0 !important;
    transition: transform 0.2s ease;
  }
  .message-2qnXI6:hover,
  .messageListItem-ZZ7v6g:hover {
    transform: scale(1.02);
    background-color: rgba(255, 230, 235, 0.9) !important;
  }

  /* Nomes dos usuários */
  span[class*="username"],
  .header-2jRmjb .username-h_Y3Us,
  .name-3Uvkvr {
    color: #d17b9f !important;
    font-weight: bold !important;
    font-family: "Comic Neue", cursive !important;
  }

  /* Links */
  a {
    color: #ff80ab !important;
    text-decoration: none !important;
  }
  a:hover {
    text-decoration: underline !important;
    color: #ff4d88 !important;
  }

  /* Botões */
  button,
  .button-1EGGcP,
  .lookFilled-1Gx00P {
    background-color: #ffd6e0 !important;
    color: #4a4a4a !important;
    border-radius: 10px !important;
    transition: 0.3s;
  }
  button:hover,
  .button-1EGGcP:hover,
  .lookFilled-1Gx00P:hover {
    background-color: #ffb6c9 !important;
    color: #ffffff !important;
    box-shadow: 0 0 10px #ff80ab;
  }

  /* Caixa de digitação */
  .textArea-2Spzkt,
  .scrollableContainer-15eg7h,
  .channelTextArea-1FufC0 {
    background-color: rgba(255, 230, 235, 0.85) !important;
    border: 2px solid #ffb6c9 !important;
    border-radius: 10px !important;
    color: #4a4a4a !important;
    transition: border-color 0.3s ease;
  }
  .textArea-2Spzkt:focus,
  .scrollableContainer-15eg7h:focus-within {
    border-color: #ff80ab !important;
    box-shadow: 0 0 8px #ff80ab;
  }
}
